                                      _mm_mul_ps(inputImag,impulseImag));
            const auto imag=_mm_add_ps(_mm_add_ps(outputImag,_mm_mul_ps(inputReal,impulseImag)),
                                      _mm_mul_ps(inputImag,impulseReal));
